// The first 421 bytes of two real Deezer MP3_128 files: the Info frame
// (header, empty side info, "Info" fields, TOC, LAME extension) plus the
// header of the first audio frame. No audio data.

const fromBase64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

/** Pink Floyd, "Speak to Me" (Deezer 116914016): a "Lame3.100" tag, 1 046 150 bytes, no ID3. */
export const SPEAK_TO_ME_HEAD = fromBase64(
	""
);
export const SPEAK_TO_ME_LENGTH = 1_046_150;

/** Daft Punk, "Robot Rock / Oh Yeah" (Alive 2007, Deezer 3167839): a "LAME3.99r" tag, 6 201 259 bytes. */
export const ROBOT_ROCK_HEAD = fromBase64(
	""
);
export const ROBOT_ROCK_LENGTH = 6_201_259;
